--
-- Table structure for table `assets`
--

DROP TABLE IF EXISTS `assets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `assets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kategori` varchar(255) NOT NULL,
  `brand` varchar(255) NOT NULL,
  `tipe` varchar(255) NOT NULL,
  `nama_perangkat` varchar(255) NOT NULL,
  `no_serial` varchar(255) DEFAULT NULL,
  `no_asset` varchar(255) NOT NULL,
  `qr_code` varchar(255) DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'active',
  `assigned_user_id` bigint(20) unsigned DEFAULT NULL,
  `operating_unit` varchar(255) DEFAULT NULL,
  `site_location_asset` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `assets_no_asset_unique` (`no_asset`),
  KEY `assets_operating_unit_foreign` (`operating_unit`),
  KEY `assets_assigned_user_id_foreign` (`assigned_user_id`),
  CONSTRAINT `assets_assigned_user_id_foreign` FOREIGN KEY (`assigned_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `assets_operating_unit_foreign` FOREIGN KEY (`operating_unit`) REFERENCES `sites` (`id_site`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=457 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

