--
-- Table structure for table `form_perawatan`
--

DROP TABLE IF EXISTS `form_perawatan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `form_perawatan` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `nomor_form` varchar(255) NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `pengguna_id` bigint(20) unsigned DEFAULT NULL,
  `asset_id` bigint(20) unsigned DEFAULT NULL,
  `site_location` varchar(255) DEFAULT NULL,
  `location_detail` varchar(255) DEFAULT NULL,
  `kondisi_akhir` enum('good_normal','caution_poor','good','fair','critical','poor') DEFAULT NULL,
  `kondisi_akhir_notes` text DEFAULT NULL,
  `barcode_fisik` tinyint(1) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `status` enum('draft','submitted','diketahui','disetujui','selesai','revisi') NOT NULL DEFAULT 'draft',
  `submitted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `form_perawatan_nomor_form_unique` (`nomor_form`),
  KEY `form_perawatan_user_id_foreign` (`user_id`),
  KEY `form_perawatan_pengguna_id_foreign` (`pengguna_id`),
  KEY `form_perawatan_asset_id_foreign` (`asset_id`),
  CONSTRAINT `form_perawatan_asset_id_foreign` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `form_perawatan_pengguna_id_foreign` FOREIGN KEY (`pengguna_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `form_perawatan_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=269 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

