DROP TABLE IF EXISTS `form_perawatan_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `form_perawatan_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `form_perawatan_id` bigint(20) unsigned NOT NULL,
  `template_item_id` bigint(20) unsigned DEFAULT NULL,
  `category` enum('hardware','aplikasi','operating_system') NOT NULL,
  `name` varchar(255) NOT NULL,
  `status` enum('baik','tidak_baik') DEFAULT NULL,
  `keterangan` text DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `form_perawatan_items_form_perawatan_id_foreign` (`form_perawatan_id`),
  KEY `form_perawatan_items_template_item_id_foreign` (`template_item_id`),
  CONSTRAINT `form_perawatan_items_form_perawatan_id_foreign` FOREIGN KEY (`form_perawatan_id`) REFERENCES `form_perawatan` (`id`) ON DELETE CASCADE,
  CONSTRAINT `form_perawatan_items_template_item_id_foreign` FOREIGN KEY (`template_item_id`) REFERENCES `checklist_template_items` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2395 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

